const paid=c=>Math.round(state.payments.filter(p=>p.consignmentId===c.id).reduce((n,p)=>n+Number(p.amount),0)*100)/100;
const balance=c=>Math.max(0,Math.round((total(c)-paid(c))*100)/100);
const nextId=(prefix,items,start)=>prefix+(Math.max(start-1,...items.map(x=>Number(x.id.replace(prefix,''))||0))+1);
