function shipmentTable(items,full=false){return table(full?['Consignment / customer','Route','Cargo','Status','Balance','Actions']:['Consignment','Route','Status',''],items.map(c=>'<tr><td><button class="record-link" data-action="openBooking" data-id="'+c.id+'">'+c.id+'</button><small>'+esc(customer(c.customerId)?.name||c.sender)+'</small></td><td>'+esc(c.origin)+' <span class="muted">→</span> '+esc(c.destination)+'<small>Due '+date(c.dueDate)+'</small></td>'+(full?'<td>'+c.packages+' packages<small>'+c.weight+' kg · '+c.volume+' m³</small></td>':'')+'<td>'+badge(c.status)+'</td>'+(full?'<td>'+money(balance(c))+'<small>AED outstanding</small></td><td><div class="row-actions"><button class="button link" data-action="openBooking" data-id="'+c.id+'">Open</button><button class="button link" data-action="editBooking" data-id="'+c.id+'">Edit</button></div></td>':'<td><button class="button link" data-action="openBooking" data-id="'+c.id+'">View</button></td>')+'</tr>').join('')||noRows(full?6:4))}
