 const charges='<div class="balance"><p>Outstanding balance · AED</p><strong>'+money(balance(c))+'</strong></div><div class="panel-body">'+chargeKeys.map((k,i)=>'<div class="charge-row"><span>'+chargeLabels[i]+'</span><b>'+money(c[k])+'</b></div>').join('')+'<div class="charge-row total"><span>Total charges</span><span>AED '+money(total(c))+'</span></div><div class="charge-row"><span>Payments received</span><b>'+money(paid(c))+'</b></div><div class="actions" style="margin-top:20px">'+btn('Record payment','payment',c.id,true)+'</div></div>';
