function customers(){const items=state.customers.filter(c=>(c.name+' '+c.contact+' '+c.phone).toLowerCase().includes(query.toLowerCase()));return head('Customers','A shared history of enquiries, shipments and collections.',btn(svg('plus')+' Add customer','newCustomer','',true))+'<section class="panel">'+searchToolbar('Search customer or contact')+table(['Customer','Contact','Shipments','Outstanding','Actions'],items.map(c=>{const cs=state.consignments.filter(s=>s.customerId===c.id);return '<tr><td><button class="record-link" data-action="openCustomer" data-id="'+c.id+'">'+esc(c.name)+'</button><small>'+c.type+' · '+c.id+'</small></td><td>'+esc(c.contact)+'<small>'+esc(c.phone)+'</small></td><td>'+cs.length+'</td><td>AED '+money(cs.reduce((n,s)=>n+balance(s),0))+'</td><td><div class="row-actions"><button class="button link" data-action="openCustomer" data-id="'+c.id+'">View</button><button class="button link" data-action="editCustomer" data-id="'+c.id+'">Edit</button></div></td></tr>'}).join('')||noRows(5))+'</section>'}
function customerDetail(){const c=customer(current);if(!c)return '';const cs=state.consignments.filter(s=>s.customerId===c.id),qs=state.quotes.filter(q=>q.customerId===c.id),ps=state.payments.filter(p=>cs.some(s=>s.id===p.consignmentId));return head(c.name,c.id+' · '+c.type+' customer',btn('Back to customers','backCustomers')+btn('Edit profile','editCustomer',c.id)+btn('Create quote','customerQuote',c.id,true))+'<div class="detail-grid">'+panel('Relationship history',cs.length+' shipments · '+qs.length+' quotations',shipmentTable(cs))+'<div>'+panel('Customer profile','', '<div class="panel-body">'+keys([['Contact',c.contact],['Phone',c.phone],['Email',c.email],['Address',c.address]])+'<h3 style="margin-top:24px">Office notes</h3><p class="muted" style="margin-top:8px">'+esc(c.notes)+'</p></div>')+'</div></div><div style="height:24px"></div>'+panel('Quotations & receipts','Linked customer activity','<div class="panel-body"><div class="timeline">'+qs.map(q=>'<div class="timeline-item"><button class="record-link" data-action="openQuote" data-id="'+q.id+'">'+q.id+' · '+q.status+'</button><small>'+esc(q.origin+' → '+q.destination)+' · AED '+money(total(q))+'</small></div>').join('')+ps.map(p=>'<div class="timeline-item">'+esc(p.id)+' · AED '+money(p.amount)+' received<small>'+p.consignmentId+' · '+date(p.date)+' · '+esc(p.method)+'</small></div>').join('')+'</div></div>')}
function leads(){const items=state.leads.filter(l=>(!filter||l.stage===filter)&&(l.name+' '+l.description+' '+l.destination).toLowerCase().includes(query.toLowerCase()));return head('Enquiries','Turn a conversation into a customer, quotation and booking.',btn(svg('plus')+' New enquiry','newLead','',true))+'<section class="panel">'+searchToolbar('Search customer, cargo or route',['New','Contacted','Quoted','Booked','Lost'])+table(['Enquiry / customer','Cargo & route','Stage','Linked quote','Actions'],items.map(l=>'<tr><td><button class="record-link" data-action="editLead" data-id="'+l.id+'">'+esc(l.name)+'</button><small>'+l.id+' · '+esc(l.contact)+'</small></td><td>'+esc(l.origin+' → '+l.destination)+'<small>'+esc(l.description)+'</small></td><td>'+badge(l.stage)+'</td><td>'+(l.quoteId?'<button class="button link" data-action="openQuote" data-id="'+l.quoteId+'">'+l.quoteId+'</button>':'—')+'</td><td><div class="row-actions"><button class="button link" data-action="editLead" data-id="'+l.id+'">Open / edit</button><button class="button link" data-action="leadQuote" data-id="'+l.id+'">'+(l.quoteId?'View quote':'Create quote')+'</button></div></td></tr>').join('')||noRows(5))+'</section>'}
function quotes(){const items=state.quotes.filter(q=>(!filter||q.status===filter)&&(q.id+' '+customer(q.customerId)?.name+' '+q.destination).toLowerCase().includes(query.toLowerCase()));return head('Quotations','Agree sample charges before cargo is booked.',btn(svg('plus')+' Create quote','createQuote','',true))+'<section class="panel">'+searchToolbar('Search quotation, customer or route',['Draft','Sent','Accepted','Booked'])+table(['Quotation / customer','Route','Total AED','Valid until','Status','Actions'],items.map(q=>'<tr><td><button class="record-link" data-action="openQuote" data-id="'+q.id+'">'+q.id+'</button><small>'+esc(customer(q.customerId)?.name)+'</small></td><td>'+esc(q.origin+' → '+q.destination)+'</td><td>'+money(total(q))+'</td><td>'+date(q.validUntil)+'</td><td>'+badge(q.status)+'</td><td><div class="row-actions"><button class="button link" data-action="openQuote" data-id="'+q.id+'">Open</button><button class="button link" data-action="editQuote" data-id="'+q.id+'">Edit</button></div></td></tr>').join('')||noRows(6))+'</section>'}
function quoteDetail(){const q=state.quotes.find(q=>q.id===current);if(!q)return '';return head(q.id,customer(q.customerId)?.name+' · '+q.origin+' to '+q.destination,btn('Back to quotes','backQuotes')+btn('Edit quote','editQuote',q.id)+btn(q.consignmentId?'Open consignment':'Accept & book','bookQuote',q.id,true))+'<div class="detail-grid">'+panel('Quotation details','', '<div class="panel-body">'+keys([['Customer',customer(q.customerId)?.name],['Status',q.status],['Cargo',q.description],['Packages',q.packages],['Weight',q.weight+' kg'],['Volume',q.volume+' m³'],['Payment basis',q.payer],['Valid until',date(q.validUntil)]])+'<div class="note" style="margin-top:24px">'+esc(q.notes)+'</div><div class="actions">'+btn('Preview / download PDF','quoteDocument',q.id)+btn('Simulate sending quote','sendQuote',q.id)+'</div>'+(q.consignmentId?'<p class="muted" style="margin-top:20px">Linked booking: '+q.consignmentId+'. Repeat conversion opens the same booking.</p>':'')+'</div>')+panel('Sample charges','AED · editable in quotation','<div class="panel-body">'+chargeKeys.map((k,i)=>'<div class="charge-row"><span>'+chargeLabels[i]+'</span><b>'+money(q[k])+'</b></div>').join('')+'<div class="charge-row total"><span>Total</span><b>'+money(total(q))+'</b></div></div>')+'</div>'}
function taskList(items){return '<div class="task-list">'+(items.map(t=>'<div class="task"><input type="checkbox" aria-label="Complete '+esc(t.title)+'" data-task="'+t.id+'" '+(t.done?'checked':'')+'><div><button class="record-link" data-action="editTask" data-id="'+t.id+'">'+esc(t.title)+'</button><small>'+esc(t.related||'Office follow-up')+' · '+esc(t.owner)+'</small></div><time>'+date(t.due)+'</time></div>').join('')||'<div class="empty">No follow-ups in this view.</div>')+'</div>'}
function tasks(){const items=state.tasks.filter(t=>(!filter||filter==='Completed'===t.done)&&(t.title+' '+t.related+' '+t.owner).toLowerCase().includes(query.toLowerCase()));return head('Follow-ups','Give every customer conversation and shipment a next action.',btn(svg('plus')+' Add follow-up','newTask','',true))+'<section class="panel">'+searchToolbar('Search task, record or owner',['Open','Completed'])+taskList(items)+'</section>'}
function collections(){const items=state.consignments.filter(c=>(!filter||(filter==='Outstanding'?balance(c)>0:balance(c)===0))&&(c.id+' '+c.sender).toLowerCase().includes(query.toLowerCase()));return head('Collections & balances','Simple charges, receipts and outstanding balances. Full accounting is outside this demo.',btn(svg('download')+' Export ledger CSV','exportLedger'))+'<section class="panel">'+searchToolbar('Search consignment or customer',['Outstanding','Paid'])+table(['Consignment / payer','Charges AED','Received AED','Outstanding AED','Actions'],items.map(c=>'<tr><td><button class="record-link" data-action="openBooking" data-id="'+c.id+'">'+c.id+'</button><small>'+esc(c.sender)+' · '+esc(c.payer)+'</small></td><td>'+money(total(c))+'</td><td>'+money(paid(c))+'</td><td>'+badge(balance(c)>0?'AED '+money(balance(c)):'Paid')+'</td><td><button class="button link" data-action="payment" data-id="'+c.id+'">Record payment</button></td></tr>').join('')||noRows(5))+'</section><div style="height:24px"></div>'+panel('Receipt ledger','All entries are local demo records',table(['Receipt','Date','Consignment','Method','Amount AED'],state.payments.slice().reverse().map(p=>'<tr><td>'+p.id+'<small>'+esc(p.reference)+'</small></td><td>'+date(p.date)+'</td><td>'+p.consignmentId+'</td><td>'+esc(p.method)+'</td><td>'+money(p.amount)+'</td></tr>').join('')))}
function reports(){const charges=state.consignments.reduce((n,c)=>n+total(c),0),payments=state.payments.reduce((n,p)=>n+p.amount,0);return head('Operations reports','A full-sheet register and daily collections summary from linked demo records.',btn('Full-sheet preview','registerPreview')+btn(svg('download')+' Download register CSV','exportRegister'))+'<div class="note">Reports use net sample charges, without tax or general-ledger accounting. “Full sheet” is implemented as a shipment register; confirm the client’s preferred print format.</div><div class="report-grid">'+panel('Charges & collections','All demo bookings','<div class="panel-body">'+[['Total booked charges',charges],['Payments received',payments],['Outstanding balance',charges-payments]].map(([k,v])=>'<div class="report-metric"><span>'+k+'</span><strong>AED '+money(v)+'</strong></div>').join('')+'</div>')+panel('Shipment summary','Current operational stages','<div class="panel-body">'+stages.map(s=>'<div class="report-metric"><span>'+s+'</span><strong>'+state.consignments.filter(c=>c.status===s).length+'</strong></div>').join('')+'</div>')+'</div><div style="height:24px"></div>'+panel('Daily collections','Receipt totals by date',table(['Date','Receipts','Cash AED','Other methods AED','Total AED'],[...new Set(state.payments.map(p=>p.date))].sort().reverse().map(d=>{const ps=state.payments.filter(p=>p.date===d);return '<tr><td>'+date(d)+'</td><td>'+ps.length+'</td><td>'+money(ps.filter(p=>p.method==='Cash').reduce((n,p)=>n+p.amount,0))+'</td><td>'+money(ps.filter(p=>p.method!=='Cash').reduce((n,p)=>n+p.amount,0))+'</td><td>'+money(ps.reduce((n,p)=>n+p.amount,0))+'</td></tr>'}).join('')))}
function field(label,name,value='',type='text',attrs=''){return '<label>'+label+'<input type="'+type+'" name="'+name+'" value="'+esc(value)+'" '+attrs+'></label>'}
function area(label,name,value='',cls=''){return '<label class="'+cls+'">'+label+'<textarea name="'+name+'">'+esc(value)+'</textarea></label>'}
function selectField(label,name,values,value='',required=false){return '<label>'+label+'<select name="'+name+'" '+(required?'required':'')+'>'+values.map(v=>{const [id,text]=Array.isArray(v)?v:[v,v];return '<option value="'+esc(id)+'" '+(String(value)===String(id)?'selected':'')+'>'+esc(text)+'</option>'}).join('')+'</select></label>'}
const num=(label,name,value,attrs='')=>field(label,name,value,'number','min="0" step="0.01" '+attrs);
function section(title,sub,body){return '<section class="form-section"><h2>'+title+'</h2><p>'+sub+'</p>'+body+'</section>'}
const customerOptions=()=>[['','Select a customer'],...state.customers.map(c=>[c.id,c.name])];
function cargoFields(c){return '<div class="form-grid">'+field('Origin *','origin',c.origin||'Dubai','text','required')+field('Destination *','destination',c.destination||'','text','required')+num('Number of packages *','packages',c.packages||1,'step="1" min="1" required')+num('Actual weight · kg *','weight',c.weight||0,'required')+num('Volume · m³','volume',c.volume||0)+num('Sample volumetric factor · kg/m³','volumetricFactor',c.volumetricFactor??167)+area('Cargo description *','description',c.description||'','span3')+'</div>'}
function chargesFields(c){return '<div class="note">Sample AED rates only. Volumetric weight = volume × factor; suggested freight = max(actual, volumetric weight) × rate. Apply the suggestion explicitly or enter agreed freight.</div><div class="form-grid">'+num('Sample rate · AED / kg','rate',c.rate??5)+selectField('Payment basis','payer',['Contract','Cash','Shipper account','Consignee account','Cash on delivery'],c.payer||'Cash')+'<div style="align-self:end">'+btn('Apply suggested freight','applyRate')+'</div>'+chargeKeys.map((k,i)=>num(chargeLabels[i]+' · AED',k,c[k]??(k==='documentation'?25:0))).join('')+'</div><div class="calculation" id="calculation" aria-live="polite"></div>'}
function bookingForm(id){
 const c=state.consignments.find(c=>c.id===id)||current?.draft||{bookingDate:TODAY,dueDate:'2026-10-09'};
 const edit=!!c.id;
 return '<div class="form-page">'+head(edit?'Edit '+c.id:'Create consignment','Enter a booking in clear sections. All values are saved locally.')+'<form id="bookingForm" data-id="'+(c.id||'')+'">'+section('Booking & customer','Choose the customer first to populate the sender.','<div class="form-grid">'+selectField('Customer *','customerId',customerOptions(),c.customerId,true)+field('Booking date *','bookingDate',c.bookingDate||TODAY,'date','required')+field('Shipper reference','shipperRef',c.shipperRef||'')+'</div>')+section('Sender & receiver','Contacts and addresses used on the consignment note.','<div class="form-grid two">'+field('Sender / shipper *','sender',c.sender||'','text','required')+field('Receiver / consignee *','receiver',c.receiver||'','text','required')+field('Sender contact *','senderContact',c.senderContact||'','text','required')+field('Receiver contact *','receiverContact',c.receiverContact||'','text','required')+field('Sender telephone *','senderPhone',c.senderPhone||'','tel','required')+field('Receiver telephone *','receiverPhone',c.receiverPhone||'','tel','required')+area('Pickup address','senderAddress',c.senderAddress||'')+area('Delivery address','receiverAddress',c.receiverAddress||'')+'</div>')+section('Cargo & route','Record actual measurements; the volumetric rule is a sample.',cargoFields(c))+section('Charges & payer','Agree and record charges before dispatch.',chargesFields(c))+section('Handling & schedule','Collection and delivery signoffs are recorded from the booking detail.','<div class="form-grid">'+field('Expected delivery','dueDate',c.dueDate||'','date')+field('Courier / team','courier',c.courier||'Demo route team')+field('Linked quotation','quoteId',c.quoteId||'','text','readonly')+area('Remarks / handling instructions','remarks',c.remarks||'','span3')+'</div>')+'<p id="formError" class="error" role="alert"></p><div class="form-footer">'+btn('Cancel','cancelBooking',c.id||'')+'<small>Fictional records · local browser storage</small><button class="button primary" type="submit">'+(edit?'Save changes':'Create consignment')+'</button></div></form></div>';
}
function quoteForm(id){const q=state.quotes.find(q=>q.id===id)||current?.draft||{};return '<div class="form-page">'+head(q.id?'Edit '+q.id:'Create quotation','A quotation becomes one linked consignment when accepted.')+'<form id="quoteForm" data-id="'+(q.id||'')+'">'+section('Customer & validity','Select an existing customer or add a profile from Customers.','<div class="form-grid">'+selectField('Customer *','customerId',customerOptions(),q.customerId,true)+field('Valid until *','validUntil',q.validUntil||'2026-10-14','date','required')+selectField('Status','status',q.consignmentId?['Booked']:['Draft','Sent','Accepted'],q.status||'Draft')+'</div>')+section('Cargo & route','The booking will inherit these details.',cargoFields(q))+section('Quotation charges','Use editable sample rates or enter agreed amounts.',chargesFields(q))+section('Notes','No approved terms or carrier commitments are implied.',area('Quotation notes','notes',q.notes||'Sample AED rates; subject to final cargo measurement.'))+'<p id="formError" class="error" role="alert"></p><div class="form-footer">'+btn('Cancel','cancelQuote',q.id||'')+'<small>Sample quotation · no real message is sent</small><button type="submit" class="button primary">Save quotation</button></div></form></div>'}
function updateCalc(){const f=document.querySelector('#bookingForm,#quoteForm');if(!f)return;const v=Object.fromEntries(new FormData(f)),vol=Number(v.volume)*Number(v.volumetricFactor),bill=Math.max(Number(v.weight),vol),sum=chargeKeys.reduce((n,k)=>n+Number(v[k]||0),0);document.querySelector('#calculation').innerHTML='<div><small>Volumetric weight</small><strong>'+vol.toFixed(2)+' kg</strong></div><div><small>Chargeable weight</small><strong>'+bill.toFixed(2)+' kg</strong></div><div><small>Suggested freight</small><strong>AED '+money(bill*Number(v.rate))+'</strong></div><div><small>Total charges</small><strong>AED '+money(sum)+'</strong></div>'}
function openDialog(title,sub,body,wide=false){document.querySelector('#dialogTitle').textContent=title;document.querySelector('#dialogSubtitle').textContent=sub;document.querySelector('#dialogBody').innerHTML=body;dialog.classList.toggle('document-dialog',wide);dialog.showModal()}
function formDialog(title,body,type,id=''){openDialog(title,'All changes stay in this fictional demo.','<form id="'+type+'Form" data-id="'+id+'">'+body+'<p class="error" id="dialogError" role="alert"></p><div class="form-footer">'+btn('Cancel','close')+'<button class="button primary" type="submit">Save '+type+'</button></div></form>')}
function customerDialog(id=''){const c=customer(id)||{};formDialog(id?'Edit customer':'Add customer','<div class="form-grid two">'+field('Customer / company *','name',c.name||'','text','required')+selectField('Customer type','type',['Business','Individual'],c.type||'Business')+field('Contact person *','contact',c.contact||'','text','required')+field('Telephone *','phone',c.phone||'','tel','required')+field('Email','email',c.email||'','email')+field('Address','address',c.address||'')+area('Office notes','notes',c.notes||'','span2')+'</div>','customer',id)}
function leadDialog(id=''){const l=state.leads.find(l=>l.id===id)||{};formDialog(id?'Enquiry '+id:'New enquiry','<div class="form-grid two">'+field('Customer / company *','name',l.name||'','text','required')+field('Contact person *','contact',l.contact||'','text','required')+field('Telephone *','phone',l.phone||'','tel','required')+field('Email','email',l.email||'','email')+field('Origin *','origin',l.origin||'Dubai','text','required')+field('Destination *','destination',l.destination||'','text','required')+num('Weight · kg','weight',l.weight||0)+num('Packages','packages',l.packages||1,'step="1" min="1"')+selectField('Stage','stage',l.quoteId?['Quoted','Booked','Lost']:['New','Contacted','Lost'],l.stage||'New')+area('Cargo description *','description',l.description||'','span2')+area('Notes / next action','notes',l.notes||'','span2')+'</div>','lead',id)}
function taskDialog(id=''){const t=state.tasks.find(t=>t.id===id)||{};formDialog(id?'Edit follow-up':'Add follow-up','<div class="form-grid two">'+field('Task *','title',t.title||'','text','required')+field('Related record','related',t.related||'')+field('Owner *','owner',t.owner||'Operations','text','required')+field('Due date *','due',t.due||TODAY,'date','required')+selectField('Progress','done',[['false','Open'],['true','Completed']],String(t.done||false))+'</div>','task',id)}
function paymentDialog(id){const c=state.consignments.find(c=>c.id===id);if(!balance(c)){toast('This consignment is fully paid.');return}formDialog('Record payment · '+id,'<div class="note">Outstanding: AED '+money(balance(c))+'. Recording a receipt does not transfer money.</div><div class="form-grid two">'+num('Amount · AED *','amount',balance(c),'min="0.01" max="'+balance(c)+'" required')+field('Receipt date *','date',TODAY,'date','required')+selectField('Method','method',['Cash','Card (simulated)','Bank transfer (simulated)'],'Cash')+field('Receipt reference *','reference','','text','required')+'</div>','payment',id)}
function signoffDialog(id,deliveryOnly=false){const c=state.consignments.find(c=>c.id===id);const fields=p=>'<h3 style="margin:20px 0 12px">'+(p==='collection'?'Collection acknowledgement':'Delivery acknowledgement')+'</h3><div class="form-grid two">'+field('Name'+(p==='delivery'?' *':''),p+'Name',c[p+'Name']||'','text',p==='delivery'?'required':'')+field('Date'+(p==='delivery'?' *':''),p+'Date',c[p+'Date']||(deliveryOnly?TODAY:''),'date',p==='delivery'?'required':'')+field('Time'+(p==='delivery'?' *':''),p+'Time',c[p+'Time']||(deliveryOnly?'14:00':''),'time',p==='delivery'?'required':'')+field('Acknowledgement / signature text'+(p==='delivery'?' *':''),p+'Signature',c[p+'Signature']||'','text',p==='delivery'?'required':'')+'</div>';formDialog('Collection & delivery signoff','<div class="note">Typed acknowledgement is a demonstration record, not a verified electronic signature. Saving a complete delivery acknowledgement marks this consignment Delivered.</div>'+(!deliveryOnly?fields('collection'):'')+fields('delivery')+field('Courier / team','courier',c.courier||'Demo route team'),'signoff',id)}
function values(form){const v=Object.fromEntries(new FormData(form));for(const k of ['packages','weight','volume','volumetricFactor','rate','amount',...chargeKeys])if(k in v)v[k]=Number(v[k]);for(const k in v)if(typeof v[k]==='string')v[k]=v[k].trim();return v}
function validateAmounts(v){return ['weight','volume','volumetricFactor','rate',...chargeKeys].every(k=>!(k in v)||Number.isFinite(v[k])&&v[k]>=0)&&(!('packages'in v)||Number.isInteger(v.packages)&&v.packages>0)}
function formError(f,msg){(f.querySelector('.error')||document.querySelector('#formError')).textContent=msg}
document.addEventListener('submit',e=>{
 const f=e.target;if(!f.id.endsWith('Form'))return;e.preventDefault();const v=values(f),id=f.dataset.id;
 if(!validateAmounts(v))return formError(f,'Enter positive package counts and non-negative finite weights and charges.');
 if(['bookingForm','quoteForm','leadForm'].includes(f.id)&&!v.description)return formError(f,'Enter a cargo description before saving.');
 if(f.id==='bookingForm'){
  const existing=state.consignments.find(c=>c.id===id),draft=current?.draft;
  if(!customer(v.customerId))return formError(f,'Choose an existing customer.');
  if(existing&&total(v)<paid(existing))return formError(f,'Charges cannot fall below receipts already recorded. Adjust the charges or review the ledger.');
  if(existing){Object.assign(existing,v);existing.history.push({text:'Booking details updated',at:stamp()});current=existing.id}
  else{const c={...v,id:nextId('CN-',state.consignments,260709),status:'Booked',history:[{text:'Consignment booked',at:stamp()}],quoteId:draft?.quoteId||v.quoteId||null};state.consignments.push(c);current=c.id;if(c.quoteId){const q=state.quotes.find(q=>q.id===c.quoteId);q.consignmentId=c.id;q.status='Booked';state.leads.filter(l=>l.quoteId===q.id).forEach(l=>l.stage='Booked')}}
  page='consignments-detail';save();toast(existing?'Consignment updated.':'Consignment created.');window.scrollTo(0,0)
 }else if(f.id==='quoteForm'){
  if(!customer(v.customerId))return formError(f,'Choose an existing customer.');
  const q=state.quotes.find(q=>q.id===id);if(q)Object.assign(q,v);else {const q={...v,id:nextId('QT-',state.quotes,203),consignmentId:null};state.quotes.push(q);if(current?.leadId){const l=state.leads.find(l=>l.id===current.leadId);l.quoteId=q.id;l.stage='Quoted'}current=q.id}if(id)current=id;page='quotes-detail';save();toast('Quotation saved.');window.scrollTo(0,0)
 }else if(f.id==='customerForm'){const c=customer(id);if(c)Object.assign(c,v);else state.customers.push({...v,id:nextId('CU-',state.customers,106)});dialog.close();save();toast('Customer saved.')}
 else if(f.id==='leadForm'){const l=state.leads.find(l=>l.id===id);if(l)Object.assign(l,v);else state.leads.push({...v,id:nextId('EN-',state.leads,304),customerId:null,quoteId:null});dialog.close();save();toast('Enquiry saved.')}
 else if(f.id==='taskForm'){v.done=v.done==='true';const t=state.tasks.find(t=>t.id===id);if(t)Object.assign(t,v);else state.tasks.push({...v,id:nextId('TK-',state.tasks,405)});dialog.close();save();toast('Follow-up saved.')}
 else if(f.id==='paymentForm'){const c=state.consignments.find(c=>c.id===id);if(!(v.amount>0&&v.amount<=balance(c)))return formError(f,'Enter an amount above zero and no higher than the outstanding balance.');state.payments.push({...v,id:nextId('RC-',state.payments,6),consignmentId:id});c.history.push({text:'Payment recorded · AED '+money(v.amount),at:stamp()});dialog.close();save();toast('Receipt recorded. No money was transferred.')}
 else if(f.id==='signoffForm'){const c=state.consignments.find(c=>c.id===id);if(!v.deliveryName||!v.deliveryDate||!v.deliveryTime||!v.deliverySignature)return formError(f,'Complete the delivery name, date, time and acknowledgement.');if((v.collectionDate||c.collectionDate)&&v.deliveryDate<(v.collectionDate||c.collectionDate))return formError(f,'Delivery date must be on or after collection date.');if(!(v.collectionName||c.collectionName)||!(v.collectionDate||c.collectionDate)||!(v.collectionTime||c.collectionTime)||!(v.collectionSignature||c.collectionSignature))return formError(f,'Record the collection acknowledgement before delivery.');Object.assign(c,v,{status:'Delivered'});c.history.push({text:'Delivered · acknowledged by '+v.deliveryName,at:stamp()});dialog.close();save();toast('Delivery signoff saved.')}
});
