function convertLead(id){const l=state.leads.find(l=>l.id===id);if(l.quoteId){navigate('quotes-detail',l.quoteId);return}let c=customer(l.customerId)||state.customers.find(c=>c.phone===l.phone||c.name.toLowerCase()===l.name.toLowerCase());if(!c){c={id:nextId('CU-',state.customers,106),name:l.name,contact:l.contact,phone:l.phone,email:l.email,address:l.origin+', UAE',notes:l.notes,type:'Business'};state.customers.push(c)}l.customerId=c.id;save();navigate('quotes-form',{leadId:id,draft:{customerId:c.id,origin:l.origin,destination:l.destination,description:l.description,weight:l.weight,packages:l.packages,notes:l.notes}});toast('Customer linked. Save this quotation to complete conversion.')}
function convertQuote(id){const q=state.quotes.find(q=>q.id===id);if(q.consignmentId){navigate('consignments-detail',q.consignmentId);return}const c=customer(q.customerId);navigate('consignments-form',{draft:{...q,id:undefined,quoteId:q.id,bookingDate:TODAY,dueDate:'2026-10-10',sender:c.name,senderContact:c.contact,senderPhone:c.phone,senderAddress:c.address,receiver:'',receiverContact:'',receiverPhone:'',receiverAddress:'',shipperRef:'',remarks:q.notes,courier:'Demo route team'}});toast('Quote details copied. Add receiver details to book.')}
function updateStatus(id){const c=state.consignments.find(c=>c.id===id),s=document.querySelector('#stageUpdate').value;if(s===c.status){toast('This shipment is already '+s.toLowerCase()+'.');return}if(c.status==='Delivered'){toast('A signed delivery is complete. Edit its details or reset the demo to start again.');render();return}if(s==='Delivered'){signoffDialog(id,!!c.collectionName);return}if(stages.indexOf(s)<stages.indexOf(c.status)){toast('Choose a later shipment stage. Earlier stages remain in the history.');render();return}if(stages.indexOf(s)>0&&!c.collectionName){openDialog('Confirm cargo collection','Record the handover before advancing the shipment.','<form id="collectionForm" data-stage="'+s+'" data-id="'+id+'"><div class="form-grid two">'+field('Collected from *','collectionName',c.senderContact,'text','required')+field('Collection date *','collectionDate',TODAY,'date','required')+field('Collection time *','collectionTime','10:30','time','required')+field('Acknowledgement *','collectionSignature','','text','required')+'</div><p class="error" role="alert"></p><div class="form-footer">'+btn('Cancel','close')+'<button class="button primary" type="submit">Confirm collection</button></div></form>');return}c.status=s;c.history.push({text:'Status updated: '+s,at:stamp()});save();toast('Shipment status updated.')}
document.addEventListener('submit',e=>{if(e.target.id!=='collectionForm')return;e.preventDefault();const f=e.target,c=state.consignments.find(c=>c.id===f.dataset.id),v=values(f);Object.assign(c,v,{status:f.dataset.stage||'Collected'});c.history.push({text:'Cargo collected from '+v.collectionName,at:stamp()});dialog.close();save();toast('Collection recorded.');});
