const registerRows=()=>state.consignments.map(c=>[c.id,c.bookingDate,c.sender,c.origin,c.destination,c.packages,c.weight,c.volume,c.status,c.payer,total(c),paid(c),balance(c),c.collectionDate||'',c.deliveryDate||'',c.courier]);
