// A standalone vector PDF writer. ASCII normalization preserves PDF byte offsets.
function vectorPDF(filename,title,sections){
 const clean=s=>String(s??'').normalize('NFKD').replace(/[^\x20-\x7E]/g,' ').replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)');
 let cmds=[],pages=[],y;
 const text=(x,pos,size,s)=>cmds.push('BT /F1 '+size+' Tf '+x+' '+pos+' Td ('+clean(s)+') Tj ET');
 const newPage=()=>{if(cmds.length)pages.push(cmds.join('\n'));cmds=['0.52 0.23 0.23 RG','0.52 0.23 0.23 rg','1 w','36 36 770 520 re S'];text(52,525,20,'FUSION CARGO');text(52,504,9,'Fusion Ventures | Fictional UAE office');text(520,525,14,title);text(520,504,9,filename.replace('.pdf','')+' | DEMONSTRATION');text(730,47,8,'Page '+(pages.length+1));y=480};
 const chunks=line=>{const words=String(line).replace(/\s+/g,' ').split(' '),result=[];let part='';for(let word of words){while(word.length>112){if(part){result.push(part);part=''}result.push(word.slice(0,112));word=word.slice(112)}if((part+' '+word).length>112){result.push(part);part=word}else part+=(part?' ':'')+word}if(part)result.push(part);return result.length?result:['']};
 newPage();for(const sec of sections){if(y<105)newPage();text(52,y,11,sec.title.toUpperCase());y-=17;for(const line of sec.lines){for(const chunk of chunks(line)){if(y<70){newPage();text(52,y,11,sec.title.toUpperCase()+' (CONTINUED)');y-=17}text(52,y,10,chunk);y-=14}}y-=11;cmds.push('52 '+(y+15)+' m 790 '+(y+15)+' l S')}pages.push(cmds.join('\n'));
 const objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids ['+pages.map((_,i)=>(4+i*2)+' 0 R').join(' ')+'] /Count '+pages.length+' >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>'];
 pages.forEach((stream,i)=>{objects.push('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 842 595] /Resources << /Font << /F1 3 0 R >> >> /Contents '+(5+i*2)+' 0 R >>');objects.push('<< /Length '+stream.length+' >>\nstream\n'+stream+'\nendstream')});
 let pdf='%PDF-1.4\n',offsets=[0];objects.forEach((o,i)=>{offsets.push(pdf.length);pdf+=(i+1)+' 0 obj\n'+o+'\nendobj\n'});const xref=pdf.length;pdf+='xref\n0 '+(objects.length+1)+'\n0000000000 65535 f \n'+offsets.slice(1).map(n=>String(n).padStart(10,'0')+' 00000 n \n').join('')+'trailer\n<< /Size '+(objects.length+1)+' /Root 1 0 R >>\nstartxref\n'+xref+'\n%%EOF';downloadBlob(filename,pdf,'application/pdf');return pdf
}
function bookingPDF(id){const c=state.consignments.find(c=>c.id===id);return vectorPDF(id+'.pdf','CONSIGNMENT NOTE',[{title:'Booking / shipper reference',lines:[c.id+' | Booking: '+c.bookingDate+' | Shipper ref: '+c.shipperRef]},{title:'Shipper / consignee',lines:['Sender: '+c.sender+' | '+c.senderContact+' | '+c.senderPhone,c.senderAddress,'Receiver: '+c.receiver+' | '+c.receiverContact+' | '+c.receiverPhone,c.receiverAddress]},{title:'Cargo / route / measurement',lines:[c.origin+' to '+c.destination+' | '+c.packages+' packages | '+c.description,'Weight: '+c.weight+' kg | Volume: '+c.volume+' m3 | Volumetric: '+(c.volume*c.volumetricFactor).toFixed(2)+' kg (sample factor '+c.volumetricFactor+')','Remarks: '+c.remarks]},{title:'Payment details (AED) / '+c.payer,lines:[chargeKeys.map((k,i)=>chargeLabels[i]+': '+money(c[k])).slice(0,4).join(' | '),chargeKeys.map((k,i)=>chargeLabels[i]+': '+money(c[k])).slice(4).join(' | '),'Total: '+money(total(c))+' | Received: '+money(paid(c))+' | Outstanding: '+money(balance(c))]},{title:'Collection / delivery acknowledgement',lines:['Collection: '+(c.collectionName||'____________')+' | '+(c.collectionDate||'________')+' '+(c.collectionTime||'____')+' | '+(c.collectionSignature||'Signature: ____________'),'Delivery: '+(c.deliveryName||'____________')+' | '+(c.deliveryDate||'________')+' '+(c.deliveryTime||'____')+' | '+(c.deliverySignature||'Signature: ____________'),'Courier: '+c.courier]},{title:'Sample conditions',lines:['Insurance requires confirmation; no coverage is represented. Reverse terms not supplied.','Fictional contacts, charges and typed acknowledgements. No approved legal terms.']}])}
function quotePDF(id){const q=state.quotes.find(q=>q.id===id),c=customer(q.customerId);return vectorPDF(id+'.pdf','QUOTATION',[{title:'Customer',lines:[c.name+' | '+c.contact+' | '+c.phone,c.address]},{title:'Route / cargo',lines:[q.origin+' to '+q.destination+' | '+q.description,q.packages+' packages | '+q.weight+' kg | '+q.volume+' m3 | Valid until '+q.validUntil]},{title:'Sample charges AED',lines:chargeKeys.map((k,i)=>chargeLabels[i]+': '+money(q[k])).concat(['TOTAL: AED '+money(total(q))+' | Payment basis: '+q.payer])},{title:'Notes',lines:[q.notes,'Fictional sample rates. No approved legal terms or carrier commitments.']}])}
